import{_ as t,o as a,c as i,a5 as r}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Synthetics & Imitations","description":"","frontmatter":{"title":"Synthetics & Imitations","identification":"synthetic-and-imitation"},"headers":[],"relativePath":"identification/synthetic-and-imitation.md","filePath":"identification/synthetic-and-imitation.md","lastUpdated":1790876393000}'),n={name:"identification/synthetic-and-imitation.md"};function o(s,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="synthetics-imitations" tabindex="-1">Synthetics &amp; Imitations <a class="header-anchor" href="#synthetics-imitations" aria-label="Permalink to &quot;Synthetics &amp; Imitations&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Record at least four separate dimensions: natural or laboratory-grown, treated or not, a different-material imitation, and any doublet/triplet or composite structure. Synthetics, imitations, treated materials, and composites require different evidence paths; typical clues support candidates but do not replace laboratory disclosure.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-synthetic-and-imitation-en"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-synthetic-and-imitation-en">Boundary &amp; Safety</h2><p>This page does not treat “natural” and “untreated” as synonyms, nor label every non-natural material as “fake”. Growth features, bubbles, fluorescence, spectra, and density clues may be absent, overlapping, or treatment-dependent. Use “supports/cannot exclude” language and refer formal disclosure to a qualified lab. </p></aside><h2 id="identification-steps" tabindex="-1">Identification Steps <a class="header-anchor" href="#identification-steps" aria-label="Permalink to &quot;Identification Steps&quot;">​</a></h2><p><strong>Four-dimensional disclosure protocol</strong></p><table tabindex="0"><thead><tr><th>Dimension</th><th>Question</th><th>Recorded output</th></tr></thead><tbody><tr><td>Material identity</td><td>What material or mineral is it?</td><td>Candidate, supporting/conflicting evidence, unresolved items</td></tr><tr><td>Growth origin</td><td>Natural formation or laboratory growth?</td><td>Growth clues, observation conditions, unresolved items</td></tr><tr><td>Treatment status</td><td>Could it be heated, filled, dyed, irradiated, or otherwise treated?</td><td>Treatment clues, unverified items, disclosure risk</td></tr><tr><td>Structure disclosure</td><td>Is it an imitation, doublet, triplet, or composite?</td><td>Junctions, material clues, and accessible areas</td></tr></tbody></table><p>Keep the four dimensions separate. “Emerald” does not mean “natural emerald”; “laboratory-grown” does not mean “untreated”; and “imitation” describes a material relationship, not quality or value.</p><p><strong>Evidence-layer matrix</strong></p><table tabindex="0"><thead><tr><th>Evidence layer</th><th>Can support</th><th>Cannot establish alone</th><th>Record</th></tr></thead><tbody><tr><td>Appearance/photos</td><td>Candidate formation and visible anomalies</td><td>Natural, synthetic, treatment, or origin</td><td>Light, background, mounting</td></tr><tr><td>Microscopy</td><td>Inclusion, growth, or junction clues</td><td>Absence does not exclude a category</td><td>Magnification, light, direction, image ID</td></tr><tr><td>RI/SG/optical reactions</td><td>Narrowing a material candidate</td><td>Natural/synthetic disclosure alone</td><td>Instrument, quality, repeats</td></tr><tr><td>Spectroscopy/advanced instruments</td><td>Structural, growth, or treatment clues</td><td>Final conclusions without calibration/workflow</td><td>Instrument, calibration, optical path, raw file</td></tr><tr><td>Laboratory report</td><td>Formal identity and disclosure opinion</td><td>Claims outside the report scope</td><td>Report ID, scope, limitations</td></tr></tbody></table><p><strong>How to use clues correctly</strong></p><p>Curved growth lines, bubbles, platinum-like inclusions, flow lines, unusual dispersion, UV zoning, and spectral patterns are possible supporting clues. Record magnification, light, direction, instrument, and repeats. Not seeing a feature means it was not observed under this setup; it does not prove natural origin or exclude synthesis.</p><p><strong>Scenario matrix: ask the question before selecting evidence</strong></p><table tabindex="0"><thead><tr><th>Scenario</th><th>Primary question</th><th>Educational next step</th><th>Escalation signal</th></tr></thead><tbody><tr><td>CVD/HPHT diamond</td><td>Is the material diamond, and can growth origin be disclosed?</td><td>Record visual/microscopy clues and check instrument suitability</td><td>Natural/laboratory-grown or formal disclosure needed</td></tr><tr><td>Synthetic corundum</td><td>Is it corundum, and are there laboratory-growth clues?</td><td>Cross-check RI, optical behavior, microscopy, and spectra</td><td>Overlapping clues or unclear treatment</td></tr><tr><td>Hydrothermal emerald</td><td>Can material identity and growth method be separated?</td><td>Record inclusions, optics, and equipment conditions</td><td>Natural/synthetic or treatment disclosure needed</td></tr><tr><td>Glass / cubic zirconia</td><td>Is it an imitation made from a different material?</td><td>Record structure and suitable physical clues</td><td>Mounted, composite, or conflicting results</td></tr><tr><td>Doublet / triplet</td><td>Is there a junction between different materials?</td><td>Use low-risk observation and mark inaccessible areas</td><td>Any formal structure or transaction disclosure</td></tr></tbody></table><p><strong>Recommended workflow</strong></p><ol><li>Define the task: educational screening, material candidate, or formal transaction/disclosure.</li><li>Record the specimen: photos, mounting, size, accessible surfaces, existing damage, and suspected composite structure.</li><li>Start with low-risk observation, then choose suitable physical, optical, or instrument evidence; do not add destructive tests just to confirm a hypothesis.</li><li>Label each clue as “supports candidate”, “consistent with candidate”, “cannot exclude”, or “unreliable”, preserving conditions and raw records.</li><li>Conclude separately across the four disclosure dimensions; write “pending verification” when evidence is missing.</li><li>Stop and refer to a qualified laboratory when results conflict, the specimen is inaccessible, value is high, or formal disclosure is required.</li></ol><p><strong>Stop conditions</strong></p><p>Do not turn “looks like”, “no anomaly observed”, or “one value is close” into a natural/synthetic conclusion. No fixed test set is sufficient for every CVD/HPHT, synthetic corundum, hydrothermal emerald, glass, cubic zirconia, or composite specimen.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Natural, treated, synthetic, imitation, and composite are separate disclosure dimensions, not one true/false label.</li><li>Growth lines, bubbles, platinum-like inclusions, flow lines, unusual dispersion, UV zoning, and spectra are possible clues, not mandatory features.</li><li>CVD/HPHT, synthetic corundum, and hydrothermal emerald require cross-testing chosen for the sample and equipment; no universal two-test shortcut is sufficient.</li><li>Typical SG, RI, or visual differences need conditions and sources; one value, facet edge, or “glassy” appearance cannot independently exclude a candidate.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>diamond</td><td>cubic zirconia (CZ)</td><td>Different-material imitation candidate; combine testing with formal disclosure</td></tr><tr><td>emerald</td><td>hydrothermal synthetic</td><td>Growth origin needs laboratory verification</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA: Analysis of Gemstones at GIA Laboratories</a><span>Standard gemological testing, laboratory workflow, and laboratory-grown diamond analysis examples</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>RI/SG as an identification starting point and further analysis for origin opinions</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA: Infrared Spectroscopy and Its Use in Gemology</a><span>Spectroscopy and its relationship to atomic structure and natural/synthetic/treatment clues</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Ruby</a><span>Typical ruby RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Sapphire</a><span>Typical sapphire RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Emerald</a><span>Typical emerald RI, birefringence, specific gravity, hardness, and treatment/synthetic/imitation context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Spinel</a><span>Typical spinel RI, isotropy, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Diamond</a><span>Typical diamond RI, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Zircon</a><span>Typical zircon RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA: Iolite Description</a><span>Iolite pleochroism and viewing-direction context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA: Tanzanite Description</a><span>Tanzanite pleochroism, orientation, lighting, and heat-treatment context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Peridot</a><span>Typical peridot RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ: Tsavorite and Demantoid</a><span>Green garnet colour overlap and mineral distinction context</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>',24)])])}const h=t(n,[["render",o]]);export{m as __pageData,h as default};
